def ep06(s):
    s = front(s, '1.5', 'v2 — CH-60: EV-28 تا EV-33؛ EV-04، EV-05، EV-24، EV-26 گسترش؛ KM-21 تا KM-27؛ دسته گزارش «خرید و درخواست‌ها»؛ بازبینی در نمای مکالمه (DEC-336، DEC-338)')
    s = R(s, '| ‏EV-04 | ‏پاسخ اطلاعاتی | ‏EP-01 | ‏نوع (دانشی / نبود پاسخ / پاسخ بخشی / پیشنهاد کاتالوگ / سفارش نمونه)، منبع، نسخه منبع، نتیجه بررسی متن (پذیرفته / قالبی) |',
             '| ‏EV-04 | ‏پاسخ اطلاعاتی | ‏EP-01 | ‏نوع (دانشی / نبود پاسخ / پاسخ بخشی / پیشنهاد کاتالوگ / سفارش نمونه)، منبع، نسخه منبع، نتیجه بررسی متن (پذیرفته / قالبی)؛ **v2:** زمان تأیید داده به‌کاررفته و لحن (VL-20) (DEC-336) |')
    s = R(s, '| ‏EV-05 | ‏پاسخ موجودی | ‏EP-02 | ‏شناسه گونه، نتیجه (موجود / ناموجود / نامشخص / متعارض)، شرط تعیین‌کننده (۱ تا ۷)، نسخه داده، نتیجه بررسی متن |',
             '| ‏EV-05 | ‏پاسخ موجودی | ‏EP-02 | ‏شناسه گونه، نتیجه (موجود / ناموجود / نامشخص / متعارض)، شرط تعیین‌کننده (۱ تا ۷)، نسخه داده، نتیجه بررسی متن؛ **v2:** منبع و زمان تأیید داده (DEC-336) |')
    s = R(s, '| ‏EV-24 | ‏تغییر تنظیمات (آستانه، ساعات کاری، زمان پاسخ، مسیر جایگزین) |',
             '| ‏EV-24 | ‏تغییر تنظیمات (آستانه، ساعات کاری، زمان پاسخ، مسیر جایگزین؛ **v2:** قابلیت‌های دستیار، لحن) |')
    s = R(s, '| ‏EV-26 | ‏نشانه بازبینی پاسخ خودکار | ‏EP-06 | ‏پاسخ بازبینی‌شده، نتیجه (VL-12: «پاسخ درست بود» / «پاسخ نادرست بود» / «باید به پشتیبان می‌رسید») **(CH-31)** |',
             '| ‏EV-26 | ‏نشانه بازبینی پاسخ خودکار | ‏EP-06 | ‏پاسخ بازبینی‌شده، نتیجه (VL-12: «پاسخ درست بود» / «پاسخ نادرست بود» / «باید به پشتیبان می‌رسید») **(CH-31)**؛ **v2:** محل (گفت‌وگوهای دستیار / نمای مکالمه)، «پاسخ درست» اختیاری = **اصلاح پاسخ AI** (DEC-338) |')
    s = after_line(s, '| ‏EV-27 | ‏تغییر حساب |', '\n'.join(EVS))
    s = R(s, '> ‏رویداد ممیزی (NFR-08) جدا تعریف نشده است:',
          '> ‏**v2 — نگاشت فهرست P1 بخش ششم:** پیام دریافتی EV-01 · نیت EV-28 · سؤال تکمیلی EV-03 · جست‌وجوی محصول و نتیجه EV-29 · پیشنهاد محصول EV-30 · پیشنهاد جایگزین EV-31 · تشخیص مانع خرید EV-32 · ارجاع EV-09 · پاسخ دستی ادمین EV-17 · حل مکالمه EV-21 · اصلاح پاسخ AI EV-26 (با «پاسخ درست») و EV-20 (ویرایش پیشنهاد پاسخ). هر رویداد شناسه مکالمه، زمان، نوع، داده مرتبط و نتیجه دارد (فیلدهای پایه DS-08). منبع پاسخ و زمان تأیید داده در EV-04 و EV-05.\n>\n> ‏رویداد ممیزی (NFR-08) جدا تعریف نشده است:')
    s = after_line(s, '| ‏KM-20 | ‏موجودی لحظه‌ای |', '\n'.join(KMS))
